intmain(intargc,char*argv[]){
intnThreads;
std::istringstreamarg1(argv[1]);
arg1>>nThreads;
pthread_tthread[nThreads-1];
intcode;
for(inti=0;i<nThreads-1;i++){
code=pthread_create(&thread[i],0,run,0);
if(code){
std::cerr<<"pthread_createfailed:"<<strerror(code)<<std::endl;
exit(1);
}
}
run(0);
for(inti=0;i<nThreads-1;i++){
code=pthread_join(thread[i],0);
if(code){
std::cerr<<"pthread_joinfailed:"<<strerror(code)<<std::endl;
exit(1);
}
}
return0;
}
